//! Native Swift SDK generation for Kaji.
//!
//! The generated package deliberately uses Foundation's `URLSession` and
//! `Codable` rather than a third-party HTTP or JSON runtime. It consequently
//! works in server-side Swift as well as Apple application targets without
//! making an SDK consumer adopt a dependency graph chosen by the generator.

mod package;
pub use package::{PackageExt, Settings, Swift, package, sdk};

use std::collections::BTreeMap;
use std::fmt::Write;

use anyhow::{Result, bail};
use kaji_core::{
    AdditionalProperties, Api, Field, GeneratedFile, GeneratedTree, Operation, Schema, SchemaKind,
    SchemaValue, SdkClientStyle,
};
use serde_json::Value;

const NOTICE: &str = "// Generated by Kaji. Do not edit.\n";

/// Generates a self-contained Swift Package Manager SDK below `output_dir`.
pub(crate) fn render_sdk(
    api: &Api,
    output_dir: &str,
    package_name: Option<&str>,
    style: SdkClientStyle,
) -> Result<GeneratedTree> {
    let root = normalized_root(output_dir)?;
    let package = package_name
        .filter(|value| !value.trim().is_empty())
        .map(str::to_owned)
        .unwrap_or_else(|| format!("{}-sdk", kebab_case(&api.name)));
    let module = type_name(&package);
    let mut tree = GeneratedTree::default();
    insert(
        &mut tree,
        &root,
        "Package.swift",
        package_manifest(&package, &module),
    )?;
    insert(
        &mut tree,
        &root,
        "README.md",
        readme(api, &package, &module, style),
    )?;
    insert(
        &mut tree,
        &root,
        "STYLE_GUIDE.md",
        style_guide(api, &module, style),
    )?;
    insert(
        &mut tree,
        &root,
        &format!("Sources/{module}/JSONValue.swift"),
        json_value(),
    )?;
    insert(
        &mut tree,
        &root,
        &format!("Sources/{module}/KajiClient.swift"),
        client_runtime(),
    )?;
    for schema in &api.schemas {
        insert(
            &mut tree,
            &root,
            &format!("Sources/{module}/Models/{}.swift", type_name(&schema.name)),
            render_model(schema),
        )?;
    }
    insert(
        &mut tree,
        &root,
        &format!("Sources/{module}/Operations.swift"),
        render_operations(api),
    )?;
    if style == SdkClientStyle::Namespaced {
        for (resource, operations) in operation_groups(api) {
            insert(
                &mut tree,
                &root,
                &format!("Sources/{module}/Resources/{resource}Resource.swift"),
                render_resource(&resource, &operations),
            )?;
        }
    }
    Ok(tree)
}

fn normalized_root(output_dir: &str) -> Result<String> {
    let root = output_dir.trim_matches('/');
    if root.is_empty() {
        bail!("Swift SDK output directory cannot be empty");
    }
    if root.split('/').any(|part| part == "..") {
        bail!("Swift SDK output directory cannot contain parent-directory components");
    }
    Ok(root.to_owned())
}

fn insert(tree: &mut GeneratedTree, root: &str, path: &str, contents: String) -> Result<()> {
    tree.insert(GeneratedFile::new(format!("{root}/{path}"), contents)?)
}

fn package_manifest(package: &str, module: &str) -> String {
    format!(
        "// swift-tools-version: 5.9\nimport PackageDescription\n\nlet package = Package(\n    name: {package:?},\n    platforms: [.macOS(.v13), .iOS(.v16)],\n    products: [.library(name: {module:?}, targets: [{module:?}])],\n    targets: [.target(name: {module:?})]\n)\n"
    )
}

fn readme(api: &Api, package: &str, module: &str, style: SdkClientStyle) -> String {
    let call = api.operations.first().map_or_else(
        || "// Call an operation on client.".to_owned(),
        |operation| {
            format!(
                "let response = try await client.{}()",
                function_name(&operation.id)
            )
        },
    );
    let style_note = match style {
        SdkClientStyle::Flat => "Operations are available directly on `KajiClient`.",
        SdkClientStyle::Namespaced => {
            "Operations are available directly on `KajiClient`; resource facades are also generated for navigation."
        }
    };
    format!(
        "# {package}\n\nGenerated Swift SDK for {}. {style_note}\n\n```swift\nimport {module}\n\nlet client = KajiClient(options: .init(baseURL: URL(string: \"https://api.example.com\")!))\n{call}\n```\n\nUse Swift Package Manager to add this directory as a local package or publish it to a source-control repository.\n",
        api.name
    )
}

fn style_guide(api: &Api, module: &str, style: SdkClientStyle) -> String {
    let surface = match style {
        SdkClientStyle::Flat => "Operations are direct async methods on `KajiClient`.",
        SdkClientStyle::Namespaced => {
            "Operations remain direct async methods on `KajiClient`; named resource facades delegate to those methods without duplicating HTTP behavior."
        }
    };
    format!(
        "# {} Swift SDK style guide\n\nModule: `{module}`.\n\n{surface}\n\n## Errors\n\nUnsuccessful HTTP responses throw `KajiAPIError.status`. Transport and decoding errors are surfaced unchanged so callers can use normal Swift error handling.\n\n## Authentication and hooks\n\nSet API credentials or defaults through `KajiClientOptions.headers`. `KajiClientHook` provides request and response callbacks for telemetry, tracing, or policy.\n\n## Concurrency\n\nClients, models, and JSON values are `Sendable` where Swift's standard library permits it. Every generated operation is `async`.\n",
        api.name
    )
}

fn json_value() -> String {
    format!(
        "{NOTICE}\nimport Foundation\n\n/// A lossless JSON value used for unconstrained OpenAPI schemas.\npublic enum JSONValue: Codable, Sendable, Equatable {{\n    case null\n    case bool(Bool)\n    case number(Double)\n    case string(String)\n    case array([JSONValue])\n    case object([String: JSONValue])\n\n    public init(from decoder: Decoder) throws {{\n        let container = try decoder.singleValueContainer()\n        if container.decodeNil() {{ self = .null }}\n        else if let value = try? container.decode(Bool.self) {{ self = .bool(value) }}\n        else if let value = try? container.decode(Double.self) {{ self = .number(value) }}\n        else if let value = try? container.decode(String.self) {{ self = .string(value) }}\n        else if let value = try? container.decode([JSONValue].self) {{ self = .array(value) }}\n        else {{ self = .object(try container.decode([String: JSONValue].self)) }}\n    }}\n\n    public func encode(to encoder: Encoder) throws {{\n        var container = encoder.singleValueContainer()\n        switch self {{\n        case .null: try container.encodeNil()\n        case .bool(let value): try container.encode(value)\n        case .number(let value): try container.encode(value)\n        case .string(let value): try container.encode(value)\n        case .array(let value): try container.encode(value)\n        case .object(let value): try container.encode(value)\n        }}\n    }}\n}}\n"
    )
}

fn client_runtime() -> String {
    format!(
        "{NOTICE}\nimport Foundation\n#if canImport(FoundationNetworking)\nimport FoundationNetworking\n#endif\n\npublic struct KajiClientOptions: Sendable {{\n    public var baseURL: URL\n    public var headers: [String: String]\n    public var timeout: TimeInterval\n\n    public init(baseURL: URL, headers: [String: String] = [:], timeout: TimeInterval = 30) {{\n        self.baseURL = baseURL\n        self.headers = headers\n        self.timeout = timeout\n    }}\n}}\n\npublic enum KajiAPIError: Error, Sendable {{\n    case invalidURL(String)\n    case invalidResponse\n    case status(code: Int, body: Data)\n}}\n\n/// Receives lifecycle notifications without requiring a logging framework.\npublic protocol KajiClientHook: Sendable {{\n    func willSend(_ request: URLRequest)\n    func didReceive(_ response: HTTPURLResponse, body: Data)\n}}\n\npublic final class KajiClient: @unchecked Sendable {{\n    private let options: KajiClientOptions\n    private let session: URLSession\n    private let hooks: [any KajiClientHook]\n    private let encoder = JSONEncoder()\n    private let decoder = JSONDecoder()\n\n    public init(options: KajiClientOptions, session: URLSession = .shared, hooks: [any KajiClientHook] = []) {{\n        self.options = options\n        self.session = session\n        self.hooks = hooks\n    }}\n\n    internal func makeRequest(method: String, path: String, query: [URLQueryItem] = []) throws -> URLRequest {{\n        guard var components = URLComponents(url: options.baseURL.appendingPathComponent(path.trimmingCharacters(in: CharacterSet(charactersIn: \"/\"))), resolvingAgainstBaseURL: false) else {{\n            throw KajiAPIError.invalidURL(path)\n        }}\n        components.queryItems = query.isEmpty ? nil : query\n        guard let url = components.url else {{ throw KajiAPIError.invalidURL(path) }}\n        var request = URLRequest(url: url, timeoutInterval: options.timeout)\n        request.httpMethod = method\n        request.setValue(\"application/json\", forHTTPHeaderField: \"Accept\")\n        for (name, value) in options.headers {{ request.setValue(value, forHTTPHeaderField: name) }}\n        return request\n    }}\n\n    internal func send<T: Decodable>(_ request: URLRequest, as type: T.Type) async throws -> T {{\n        hooks.forEach {{ $0.willSend(request) }}\n        let (data, response) = try await session.data(for: request)\n        guard let http = response as? HTTPURLResponse else {{ throw KajiAPIError.invalidResponse }}\n        hooks.forEach {{ $0.didReceive(http, body: data) }}\n        guard (200..<300).contains(http.statusCode) else {{ throw KajiAPIError.status(code: http.statusCode, body: data) }}\n        return try decoder.decode(T.self, from: data)\n    }}\n\n    internal func sendVoid(_ request: URLRequest) async throws {{\n        hooks.forEach {{ $0.willSend(request) }}\n        let (data, response) = try await session.data(for: request)\n        guard let http = response as? HTTPURLResponse else {{ throw KajiAPIError.invalidResponse }}\n        hooks.forEach {{ $0.didReceive(http, body: data) }}\n        guard (200..<300).contains(http.statusCode) else {{ throw KajiAPIError.status(code: http.statusCode, body: data) }}\n    }}\n\n    internal func encode<T: Encodable>(_ body: T) throws -> Data {{ try encoder.encode(body) }}\n}}\n\nextension String {{\n    var kajiPathComponent: String {{ addingPercentEncoding(withAllowedCharacters: .urlPathAllowed) ?? self }}\n}}\n"
    )
}

fn render_model(schema: &Schema) -> String {
    let name = type_name(&schema.name);
    match &schema.value.kind {
        SchemaKind::Object {
            fields,
            additional_properties,
        } => render_object(&name, fields, additional_properties),
        SchemaKind::String if !schema.value.enum_values.is_empty() => {
            render_enum(&name, &schema.value.enum_values)
        }
        _ => format!(
            "{NOTICE}\nimport Foundation\n\npublic typealias {name} = {}\n",
            swift_type(&schema.value, false)
        ),
    }
}

fn render_object(name: &str, fields: &[Field], additional: &AdditionalProperties) -> String {
    let mut output =
        format!("{NOTICE}\nimport Foundation\n\npublic struct {name}: Codable, Sendable {{\n");
    for field in fields {
        let field_name = identifier(&field.name);
        let ty = swift_type(&field.value, !field.required);
        let _ = writeln!(output, "    public var {field_name}: {ty}");
    }
    if !matches!(additional, AdditionalProperties::Forbidden) {
        output.push_str("    /// OpenAPI permits additional properties; unknown fields are retained by the server but are not modeled by this strongly typed value.\n");
    }
    output.push_str("\n    public init(");
    for (index, field) in fields.iter().enumerate() {
        let separator = if index + 1 == fields.len() { "" } else { "," };
        let default_value = if field.required { "" } else { " = nil" };
        let _ = writeln!(
            output,
            "        {}: {}{default_value}{separator}",
            identifier(&field.name),
            swift_type(&field.value, !field.required)
        );
    }
    output.push_str("    ) {\n");
    for field in fields {
        let name = identifier(&field.name);
        let _ = writeln!(output, "        self.{name} = {name}");
    }
    output.push_str("    }\n\n    enum CodingKeys: String, CodingKey {\n");
    for field in fields {
        let generated = identifier(&field.name);
        if generated == field.name {
            let _ = writeln!(output, "        case {generated}");
        } else {
            let _ = writeln!(output, "        case {generated} = {:?}", field.name);
        }
    }
    output.push_str("    }\n}\n");
    output
}

fn render_enum(name: &str, values: &[Value]) -> String {
    let mut output = format!(
        "{NOTICE}\nimport Foundation\n\npublic enum {name}: String, Codable, Sendable {{\n"
    );
    for (index, value) in values.iter().enumerate() {
        let raw = value.as_str().unwrap_or_default();
        let _ = writeln!(output, "    case {} = {:?}", enum_case(raw, index), raw);
    }
    output.push_str("}\n");
    output
}

fn render_operations(api: &Api) -> String {
    let mut output = format!("{NOTICE}\nimport Foundation\n\npublic extension KajiClient {{\n");
    for operation in &api.operations {
        output.push_str(&render_operation(operation, "    "));
    }
    output.push_str("}\n");
    output
}

fn render_operation(operation: &Operation, indent: &str) -> String {
    let name = function_name(&operation.id);
    let parameters = operation_parameters(operation);
    let response = operation
        .success_schema()
        .map(|schema| swift_type(schema, false))
        .unwrap_or_else(|| "Void".to_owned());
    let mut output = String::new();
    let _ = write!(output, "{indent}func {name}(");
    for (index, parameter) in parameters.iter().enumerate() {
        if index > 0 {
            output.push_str(", ");
        }
        output.push_str(&parameter.signature);
    }
    let _ = writeln!(output, ") async throws -> {response} {{");
    let mut path = operation.path.clone();
    for parameter in operation
        .parameters
        .iter()
        .filter(|parameter| parameter.location == "path")
    {
        let value = identifier(&parameter.name);
        let _ = writeln!(
            output,
            "{indent}    let {value}Path = String(describing: {value}).kajiPathComponent"
        );
        path = path.replace(
            &format!("{{{}}}", parameter.name),
            &format!("\\({value}Path)"),
        );
    }
    let request_binding = if operation.request_body.is_some()
        || operation
            .parameters
            .iter()
            .any(|parameter| parameter.location == "header")
    {
        "var"
    } else {
        "let"
    };
    let _ = writeln!(
        output,
        "{indent}    {request_binding} request = try makeRequest(method: {:?}, path: \"{}\", query: [",
        operation.method.as_str(),
        swift_path_literal(&path)
    );
    for parameter in operation
        .parameters
        .iter()
        .filter(|parameter| parameter.location == "query")
    {
        let value = identifier(&parameter.name);
        if parameter.required {
            let _ = writeln!(
                output,
                "{indent}        URLQueryItem(name: {:?}, value: String(describing: {value})),",
                parameter.name
            );
        } else {
            let _ = writeln!(
                output,
                "{indent}        {value}.map {{ URLQueryItem(name: {:?}, value: String(describing: $0)) }},",
                parameter.name
            );
        }
    }
    output.push_str(&format!("{indent}    ].compactMap {{ $0 }})\n"));
    for parameter in operation
        .parameters
        .iter()
        .filter(|parameter| parameter.location == "header")
    {
        let value = identifier(&parameter.name);
        if parameter.required {
            let _ = writeln!(
                output,
                "{indent}    request.setValue(String(describing: {value}), forHTTPHeaderField: {:?})",
                parameter.name
            );
        } else {
            let _ = writeln!(
                output,
                "{indent}    if let {value} {{ request.setValue(String(describing: {value}), forHTTPHeaderField: {:?}) }}",
                parameter.name
            );
        }
    }
    if let Some(body) = &operation.request_body {
        let content_type = body
            .media_types
            .first()
            .map(|media| media.content_type.as_str())
            .unwrap_or("application/json");
        let _ = writeln!(
            output,
            "{indent}    request.setValue({content_type:?}, forHTTPHeaderField: \"Content-Type\")"
        );
        if body.required {
            let _ = writeln!(output, "{indent}    request.httpBody = try encode(body)");
        } else {
            let _ = writeln!(
                output,
                "{indent}    if let body {{ request.httpBody = try encode(body) }}"
            );
        }
    }
    if response == "Void" {
        let _ = writeln!(output, "{indent}    try await sendVoid(request)");
    } else {
        let _ = writeln!(
            output,
            "{indent}    return try await send(request, as: {response}.self)"
        );
    }
    let _ = writeln!(output, "{indent}}}\n");
    output
}

struct ParameterRender {
    signature: String,
}

fn operation_parameters(operation: &Operation) -> Vec<ParameterRender> {
    let mut values = operation
        .parameters
        .iter()
        .filter(|parameter| matches!(parameter.location.as_str(), "path" | "query" | "header"))
        .map(|parameter| ParameterRender {
            signature: format!(
                "{}: {}{}",
                identifier(&parameter.name),
                parameter.schema.as_ref().map_or_else(
                    || "JSONValue".to_owned(),
                    |schema| swift_type(schema, !parameter.required)
                ),
                if parameter.required { "" } else { " = nil" }
            ),
        })
        .collect::<Vec<_>>();
    if let Some(body) = &operation.request_body {
        let ty = body
            .media_types
            .iter()
            .find(|media| {
                media.content_type == "application/json" || media.content_type.ends_with("+json")
            })
            .or_else(|| body.media_types.first())
            .and_then(|media| media.schema.as_ref())
            .map_or_else(
                || "JSONValue".to_owned(),
                |schema| swift_type(schema, !body.required),
            );
        values.push(ParameterRender {
            signature: format!("body: {ty}{}", if body.required { "" } else { " = nil" }),
        });
    }
    values
}

fn operation_groups(api: &Api) -> BTreeMap<String, Vec<&Operation>> {
    let mut groups = BTreeMap::new();
    for operation in &api.operations {
        let segment = operation
            .path
            .split('/')
            .find(|part| !part.is_empty() && !part.starts_with('{'))
            .unwrap_or("api");
        groups
            .entry(type_name(segment))
            .or_insert_with(Vec::new)
            .push(operation);
    }
    groups
}

fn render_resource(resource: &str, operations: &[&Operation]) -> String {
    let property = identifier(&lower_camel(resource));
    let mut output = format!(
        "{NOTICE}\nimport Foundation\n\npublic extension KajiClient {{\n    var {property}: {resource}Resource {{ {resource}Resource(client: self) }}\n}}\n\npublic struct {resource}Resource {{\n    private let client: KajiClient\n    internal init(client: KajiClient) {{ self.client = client }}\n"
    );
    for operation in operations {
        let name = function_name(&operation.id);
        let parameters = operation_parameters(operation);
        let response = operation
            .success_schema()
            .map(|schema| swift_type(schema, false))
            .unwrap_or_else(|| "Void".to_owned());
        let _ = write!(output, "\n    public func {name}(");
        for (index, parameter) in parameters.iter().enumerate() {
            if index > 0 {
                output.push_str(", ");
            }
            output.push_str(&parameter.signature);
        }
        let _ = writeln!(output, ") async throws -> {response} {{");
        let call_args = parameters
            .iter()
            .map(|parameter| {
                let label = parameter.signature.split(':').next().unwrap_or_default();
                format!("{label}: {label}")
            })
            .collect::<Vec<_>>()
            .join(", ");
        if response == "Void" {
            let _ = writeln!(output, "        try await client.{name}({call_args})");
        } else {
            let _ = writeln!(
                output,
                "        return try await client.{name}({call_args})"
            );
        }
        output.push_str("    }\n");
    }
    output.push_str("}\n");
    output
}

fn swift_type(schema: &SchemaValue, optional: bool) -> String {
    let mut ty = match &schema.kind {
        SchemaKind::Any
        | SchemaKind::Null
        | SchemaKind::Not { .. }
        | SchemaKind::OneOf { .. }
        | SchemaKind::AnyOf { .. }
        | SchemaKind::AllOf { .. } => "JSONValue".to_owned(),
        SchemaKind::Boolean => "Bool".to_owned(),
        SchemaKind::Integer => "Int".to_owned(),
        SchemaKind::Number => "Double".to_owned(),
        SchemaKind::String => "String".to_owned(),
        SchemaKind::Array { items } => format!("[{}]", swift_type(items, false)),
        SchemaKind::Object { .. } => "JSONValue".to_owned(),
        SchemaKind::Reference { reference } => {
            type_name(reference.rsplit('/').next().unwrap_or(reference))
        }
    };
    if optional || schema.nullable || schema.optional || schema.nullish {
        ty.push('?');
    }
    ty
}

fn type_name(value: &str) -> String {
    let result = value
        .split(|character: char| !character.is_ascii_alphanumeric())
        .filter(|part| !part.is_empty())
        .map(|part| {
            let mut chars = part.chars();
            chars.next().map_or_else(String::new, |first| {
                first.to_ascii_uppercase().to_string() + chars.as_str()
            })
        })
        .collect::<String>();
    let result = if result.is_empty() {
        "KajiAPI".to_owned()
    } else {
        result
    };
    if result
        .chars()
        .next()
        .is_some_and(|character| character.is_ascii_digit())
    {
        format!("Kaji{result}")
    } else {
        result
    }
}

fn lower_camel(value: &str) -> String {
    let upper = type_name(value);
    let mut chars = upper.chars();
    chars.next().map_or_else(
        || "api".to_owned(),
        |first| first.to_ascii_lowercase().to_string() + chars.as_str(),
    )
}

fn kebab_case(value: &str) -> String {
    let value = value
        .chars()
        .map(|character| {
            if character.is_ascii_alphanumeric() {
                character.to_ascii_lowercase()
            } else {
                '-'
            }
        })
        .collect::<String>();
    let value = value
        .split('-')
        .filter(|part| !part.is_empty())
        .collect::<Vec<_>>()
        .join("-");
    if value.is_empty() {
        "kaji".to_owned()
    } else {
        value
    }
}

fn function_name(value: &str) -> String {
    identifier(&lower_camel(value))
}

fn identifier(value: &str) -> String {
    let mut value = lower_camel(value);
    if value.is_empty() {
        value = "value".to_owned();
    }
    if value
        .chars()
        .next()
        .is_some_and(|character| character.is_ascii_digit())
    {
        value.insert(0, '_');
    }
    if matches!(
        value.as_str(),
        "as" | "associatedtype"
            | "break"
            | "case"
            | "catch"
            | "class"
            | "continue"
            | "default"
            | "defer"
            | "deinit"
            | "do"
            | "else"
            | "enum"
            | "extension"
            | "fallthrough"
            | "false"
            | "fileprivate"
            | "for"
            | "func"
            | "guard"
            | "if"
            | "import"
            | "in"
            | "init"
            | "inout"
            | "internal"
            | "is"
            | "let"
            | "nil"
            | "open"
            | "operator"
            | "private"
            | "protocol"
            | "public"
            | "repeat"
            | "return"
            | "self"
            | "static"
            | "struct"
            | "subscript"
            | "super"
            | "switch"
            | "throw"
            | "throws"
            | "true"
            | "try"
            | "typealias"
            | "var"
            | "where"
            | "while"
    ) {
        format!("`{value}`")
    } else {
        value
    }
}

fn enum_case(value: &str, index: usize) -> String {
    let name = identifier(value).trim_matches('`').to_owned();
    if name.is_empty() || name == "value" {
        format!("value{index}")
    } else {
        name
    }
}

/// Escapes only characters which terminate a Swift string. In particular, it
/// preserves `\\(expression)` interpolation inserted for OpenAPI path values.
fn swift_path_literal(value: &str) -> String {
    value
        .replace('"', "\\\"")
        .replace('\r', "\\r")
        .replace('\n', "\\n")
}

#[cfg(test)]
mod tests {
    use super::*;
    use kaji_core::{HttpMethod, OperationParameter, OperationRequestBody, OperationResponse};

    #[test]
    fn renders_a_swift_package_with_models_operations_and_resources() {
        let api = Api {
            name: "Pet Store".into(),
            version: "1.0.0".into(),
            schemas: vec![Schema::new(
                "Pet",
                SchemaValue::new(SchemaKind::Object {
                    fields: vec![Field {
                        name: "pet_id".into(),
                        value: SchemaValue::new(SchemaKind::Integer),
                        required: true,
                        annotations: BTreeMap::new(),
                    }],
                    additional_properties: AdditionalProperties::Forbidden,
                }),
            )],
            operations: vec![Operation {
                id: "listPets".into(),
                method: HttpMethod::Get,
                path: "/pets".into(),
                responses: vec![OperationResponse::json(
                    "200",
                    SchemaValue::new(SchemaKind::Array {
                        items: Box::new(SchemaValue::reference("#/components/schemas/Pet")),
                    }),
                )],
                ..Operation::default()
            }],
            ..Api::default()
        };
        let tree = render_sdk(&api, "swift", None, SdkClientStyle::Namespaced).unwrap();
        assert!(
            tree.get("swift/Package.swift")
                .unwrap()
                .contains("swift-tools-version")
        );
        assert!(
            tree.get("swift/Sources/PetStoreSdk/Models/Pet.swift")
                .unwrap()
                .contains("petId")
        );
        assert!(
            tree.get("swift/Sources/PetStoreSdk/Operations.swift")
                .unwrap()
                .contains("listPets")
        );
        assert!(
            tree.get("swift/Sources/PetStoreSdk/Resources/PetsResource.swift")
                .is_some()
        );
    }

    #[test]
    fn rejects_escaping_output() {
        assert!(render_sdk(&Api::default(), "../swift", None, SdkClientStyle::Flat).is_err());
    }

    #[test]
    #[ignore = "requires a Swift toolchain"]
    fn generated_package_builds_with_swiftpm() {
        use std::process::Command;

        let api = Api {
            name: "Example API".into(),
            version: "1.0.0".into(),
            operations: vec![
                Operation {
                    id: "listItems".into(),
                    method: HttpMethod::Get,
                    path: "/items".into(),
                    parameters: vec![OperationParameter {
                        name: "limit".into(),
                        location: "query".into(),
                        required: false,
                        schema: Some(SchemaValue::new(SchemaKind::Integer)),
                        description: None,
                        annotations: BTreeMap::new(),
                    }],
                    responses: vec![OperationResponse::json(
                        "200",
                        SchemaValue::new(SchemaKind::Array {
                            items: Box::new(SchemaValue::new(SchemaKind::String)),
                        }),
                    )],
                    ..Operation::default()
                },
                Operation {
                    id: "createItem".into(),
                    method: HttpMethod::Post,
                    path: "/items".into(),
                    request_body: Some(OperationRequestBody::json(
                        SchemaValue::new(SchemaKind::Object {
                            fields: Vec::new(),
                            additional_properties: AdditionalProperties::Any,
                        }),
                        true,
                    )),
                    ..Operation::default()
                },
            ],
            ..Api::default()
        };
        let directory = tempfile::tempdir().unwrap();
        render_sdk(&api, "sdk", None, SdkClientStyle::Namespaced)
            .unwrap()
            .write_to(directory.path())
            .unwrap();
        let output = Command::new("swift")
            .args(["build", "--disable-sandbox"])
            .current_dir(directory.path().join("sdk"))
            .output()
            .unwrap();
        assert!(
            output.status.success(),
            "{}",
            String::from_utf8_lossy(&output.stderr)
        );
    }
}
